class switch_monitor extends uvm_monitor; `uvm_component_utils(switch_monitor) virtual switch_if vif; uvm_analysis_port #(switch_item) ap; function new(string n,uvm_component p);super.new(n,p);ap=new("ap",this);endfunction function void build_phase(uvm_phase p); if(!uvm_config_db#(virtual switch_if)::get(this,"","vif",vif))`uvm_fatal("NOVIF","missing vif") endfunction task run_phase(uvm_phase p); forever begin @(posedge vif.clk); for(int d=0;d<4;d++) if(vif.out_valid[d]&&vif.out_ready[d]) begin switch_item t=switch_item::type_id::create("observed"); t.dst=d; t.data=vif.out_data[d]; ap.write(t); end end endtask endclass
